/**
 * YAML syntax validator using pattern-based validation.
 *
 * Limitations:
 * - Does not validate YAML 1.2 spec compliance (anchors, aliases, tags)
 * - Does not validate data types or schema
 * - May miss complex multi-line string edge cases
 * - Focus: structural syntax errors that prevent parsing
 */

export interface ValidationError {
  line: number;
  column?: number;
  message: string;
  context?: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

interface ParserState {
  indentLevel: number;
  openBrackets: Array<{ char: string; line: number; column: number }>;
  inQuote: { char: string; line: number; column: number } | null;
  previousIndent: number;
  indentStack: number[];
}

export function validateYaml(content: string): ValidationResult {
  const errors: ValidationError[] = [];
  const lines = content.split('\n');

  const state: ParserState = {
    indentLevel: 0,
    openBrackets: [],
    inQuote: null,
    previousIndent: 0,
    indentStack: [0],
  };

  for (let lineIndex = 0; lineIndex < lines.length; lineIndex++) {
    const line = lines[lineIndex];
    const lineNum = lineIndex + 1;

    validateLine(line, lineNum, state, errors, lines);
  }

  if (state.openBrackets.length > 0) {
    const bracket = state.openBrackets[0];
    errors.push({
      line: bracket.line,
      column: bracket.column,
      message: `Unmatched opening bracket '${bracket.char}'`,
      context: getContext(lines, bracket.line - 1),
    });
  }

  if (state.inQuote) {
    errors.push({
      line: state.inQuote.line,
      column: state.inQuote.column,
      message: `Unmatched opening quote '${state.inQuote.char}'`,
      context: getContext(lines, state.inQuote.line - 1),
    });
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

function validateLine(
  line: string,
  lineNum: number,
  state: ParserState,
  errors: ValidationError[],
  allLines: string[]
): void {
  if (line.trim().length === 0) {
    return;
  }

  const commentIndex = findCommentStart(line, state);
  const effectiveLine = commentIndex >= 0 ? line.substring(0, commentIndex) : line;

  if (effectiveLine.trim().length === 0) {
    return;
  }

  checkIndentation(effectiveLine, lineNum, state, errors, allLines);
  checkKeyValueSyntax(effectiveLine, lineNum, state, errors, allLines);
  checkListItemFormat(effectiveLine, lineNum, errors, allLines);
  updateBracketState(effectiveLine, lineNum, state);
}

function findCommentStart(line: string, state: ParserState): number {
  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"' || char === "'") {
      if (state.inQuote && state.inQuote.char === char) {
        state.inQuote = null;
      } else if (!state.inQuote) {
        state.inQuote = { char, line: 0, column: i };
      }
    }

    if (char === '#' && !state.inQuote) {
      return i;
    }
  }

  return -1;
}

function checkIndentation(
  line: string,
  lineNum: number,
  state: ParserState,
  errors: ValidationError[],
  allLines: string[]
): void {
  const indent = line.search(/\S/);

  if (indent === -1) {
    return;
  }

  const indentStr = line.substring(0, indent);
  if (indentStr.includes('\t') && indentStr.includes(' ')) {
    errors.push({
      line: lineNum,
      column: 0,
      message: 'Mixed tabs and spaces in indentation',
      context: getContext(allLines, lineNum - 1),
    });
    return;
  }

  if (indent > state.previousIndent) {
    const jump = indent - state.previousIndent;
    if (state.previousIndent > 0 && jump > 4) {
      errors.push({
        line: lineNum,
        column: 0,
        message: `Indentation jump too large - expected ${state.previousIndent + 2} spaces, found ${indent}`,
        context: getContext(allLines, lineNum - 1),
      });
    }
    state.indentStack.push(indent);
  } else if (indent < state.previousIndent) {
    while (state.indentStack.length > 0 && state.indentStack[state.indentStack.length - 1] > indent) {
      state.indentStack.pop();
    }

    if (state.indentStack.length > 0 && state.indentStack[state.indentStack.length - 1] !== indent) {
      errors.push({
        line: lineNum,
        column: 0,
        message: `Inconsistent indentation - ${indent} spaces does not match any previous level`,
        context: getContext(allLines, lineNum - 1),
      });
    }
  }

  state.previousIndent = indent;
}

function checkKeyValueSyntax(
  line: string,
  lineNum: number,
  state: ParserState,
  errors: ValidationError[],
  allLines: string[]
): void {
  const trimmed = line.trim();

  if (trimmed.startsWith('-')) {
    return;
  }

  if (trimmed.startsWith('[') || trimmed.startsWith('{')) {
    return;
  }

  if (!trimmed.includes(':')) {
    if (trimmed.length > 0 && !trimmed.match(/^[\[\]{},"']/) && !isScalarValue(trimmed)) {
      errors.push({
        line: lineNum,
        column: line.search(/\S/),
        message: 'Missing colon in key-value pair',
        context: getContext(allLines, lineNum - 1),
      });
    }
  } else {
    const colonIndex = trimmed.indexOf(':');
    const key = trimmed.substring(0, colonIndex).trim();

    if (key.length === 0) {
      errors.push({
        line: lineNum,
        column: line.indexOf(':'),
        message: 'Empty key before colon',
        context: getContext(allLines, lineNum - 1),
      });
    }
  }
}

function checkListItemFormat(
  line: string,
  lineNum: number,
  errors: ValidationError[],
  allLines: string[]
): void {
  const trimmed = line.trim();

  if (!trimmed.startsWith('-')) {
    return;
  }

  if (trimmed.length === 1) {
    return;
  }

  const afterDash = trimmed[1];
  if (afterDash !== ' ' && afterDash !== '\t') {
    errors.push({
      line: lineNum,
      column: line.indexOf('-') + 1,
      message: 'List item dash must be followed by space',
      context: getContext(allLines, lineNum - 1),
    });
  }
}

function updateBracketState(
  line: string,
  lineNum: number,
  state: ParserState
): void {
  const quoteState = { char: '', active: false };

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"' || char === "'") {
      if (quoteState.active && quoteState.char === char) {
        quoteState.active = false;
      } else if (!quoteState.active) {
        quoteState.active = true;
        quoteState.char = char;
      }
      continue;
    }

    if (quoteState.active) {
      continue;
    }

    if (char === '[' || char === '{') {
      state.openBrackets.push({ char, line: lineNum, column: i });
    } else if (char === ']') {
      if (state.openBrackets.length === 0 || state.openBrackets[state.openBrackets.length - 1].char !== '[') {
        continue;
      }
      state.openBrackets.pop();
    } else if (char === '}') {
      if (state.openBrackets.length === 0 || state.openBrackets[state.openBrackets.length - 1].char !== '{') {
        continue;
      }
      state.openBrackets.pop();
    }
  }
}

function isScalarValue(text: string): boolean {
  const scalarPatterns = [
    /^true$/i,
    /^false$/i,
    /^null$/i,
    /^~$/,
    /^-?\d+$/,
    /^-?\d+\.\d+$/,
    /^0x[0-9a-fA-F]+$/,
  ];

  return scalarPatterns.some(pattern => pattern.test(text.trim()));
}

function getContext(lines: string[], lineIndex: number): string {
  const contextLines: string[] = [];

  const start = Math.max(0, lineIndex - 1);
  const end = Math.min(lines.length - 1, lineIndex + 1);

  for (let i = start; i <= end; i++) {
    const prefix = i === lineIndex ? '> ' : '  ';
    contextLines.push(`${prefix}${lines[i]}`);
  }

  return contextLines.join('\n');
}

