#!/usr/bin/env bun

import { readFileSync } from 'fs';
import { validateYaml } from './yaml-validator.js';

function displayUsage(): void {
  console.log(`Usage: bun run validate-yaml <filepath>

Validates YAML file syntax without adding external dependencies.

Arguments:
  <filepath>    Path to the YAML file to validate

Exit codes:
  0    Valid YAML
  1    Invalid YAML
  2    I/O error (file not found, permission denied, etc.)

Examples:
  bun run validate-yaml config.yaml
  bun run validate-yaml ./configs/app.yml
`);
}

function main(): void {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    displayUsage();
    process.exit(2);
  }

  const filePath = args[0];

  try {
    const content = readFileSync(filePath, 'utf-8');
    const result = validateYaml(content);

    if (result.valid) {
      console.log(`✓ Valid YAML: ${filePath}`);
      process.exit(0);
    } else {
      console.log(`✗ Invalid YAML: ${filePath}`);
      for (const error of result.errors) {
        const columnInfo = error.column !== undefined ? `, column ${error.column}` : '';
        console.log(`  Line ${error.line}${columnInfo}: ${error.message}`);

        if (error.context) {
          const contextLines = error.context.split('\n');
          for (const line of contextLines) {
            console.log(`    ${line}`);
          }
        }
      }
      process.exit(1);
    }
  } catch (err) {
    if (err instanceof Error) {
      if ('code' in err && err.code === 'ENOENT') {
        console.error(`✗ Error: File not found: ${filePath}`);
        process.exit(2);
      } else if ('code' in err && err.code === 'EACCES') {
        console.error(`✗ Error: Permission denied: ${filePath}`);
        process.exit(2);
      } else {
        console.error(`✗ Error: ${err.message}`);
        if (process.env.DEBUG) {
          console.error(err.stack);
        }
        process.exit(2);
      }
    } else {
      console.error(`✗ Unexpected error occurred`);
      process.exit(2);
    }
  }
}

main();

