import { describe, expect, test } from "bun:test";
import { validateYaml, type ValidationResult } from "./yaml-validator";

describe("yaml-validator", () => {
  describe("valid YAML", () => {
    test("validates simple key-value pairs", () => {
      const yaml = `name: test
version: 1.0.0
enabled: true`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates nested structures", () => {
      const yaml = `server:
  host: localhost
  port: 8080
  config:
    timeout: 30
    retries: 3`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates lists with dash syntax", () => {
      const yaml = `items:
  - first
  - second
  - third`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates YAML with comments", () => {
      const yaml = `# Configuration file
name: test # inline comment
version: 1.0.0
# Another comment
enabled: true`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates YAML with inline arrays", () => {
      const yaml = `tags: [dev, test, prod]
ports: [80, 443, 8080]`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates YAML with inline objects", () => {
      const yaml = `config: {timeout: 30, retries: 3}
server: {host: localhost, port: 8080}`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates YAML with quoted strings", () => {
      const yaml = `message: "Hello, world!"
path: '/var/log/app.log'
mixed: "Contains a # hash"`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates YAML with scalar values", () => {
      const yaml = `bool_true: true
bool_false: false
null_value: null
tilde: ~
integer: 42
negative: -10
float: 3.14
hex: 0xFF`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates complex nested structure", () => {
      const yaml = `database:
  primary:
    host: db1.example.com
    port: 5432
    credentials:
      username: admin
      password: secret
  replicas:
    - host: db2.example.com
      port: 5432
    - host: db3.example.com
      port: 5432`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });
  });

  describe("invalid YAML", () => {
    test("detects inconsistent indentation", () => {
      const yaml = `server:
  host: localhost
     port: 8080`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].line).toBe(3);
      expect(result.errors[0].message).toContain("Indentation");
    });

    test("detects mixed tabs and spaces", () => {
      const yaml = `server:
\t  host: localhost`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("Mixed tabs and spaces");
    });

    test("detects unmatched opening bracket", () => {
      const yaml = `tags: [dev, test, prod
ports: [80, 443]`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("Unmatched opening bracket");
      expect(result.errors[0].message).toContain("[");
    });

    test("detects unmatched opening brace", () => {
      const yaml = `config: {timeout: 30, retries: 3
server: ok`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("Unmatched opening bracket");
      expect(result.errors[0].message).toContain("{");
    });

    test("detects unmatched quote", () => {
      const yaml = `message: "Hello, world!
name: test`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("Unmatched opening quote");
    });

    test("detects missing colon in key-value pair", () => {
      const yaml = `name: test
version 1.0.0
enabled: true`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].line).toBe(2);
      expect(result.errors[0].message).toContain("Missing colon");
    });

    test("detects empty key before colon", () => {
      const yaml = `: value
name: test`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("Empty key");
    });

    test("detects list item without space after dash", () => {
      const yaml = `items:
  - first
  -second
  - third`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].line).toBe(3);
      expect(result.errors[0].message).toContain("List item dash must be followed by space");
    });

    test("detects indentation that doesn't match previous levels", () => {
      const yaml = `server:
  host: localhost
  port: 8080
 invalid: true`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("Inconsistent indentation");
    });
  });

  describe("edge cases", () => {
    test("handles empty file", () => {
      const yaml = "";

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("handles whitespace-only file", () => {
      const yaml = "   \n\n  \n\t\n";

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("handles file with only comments", () => {
      const yaml = `# Comment 1
# Comment 2
# Comment 3`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("handles very long lines", () => {
      const longValue = "x".repeat(10000);
      const yaml = `key: ${longValue}`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("handles single line YAML", () => {
      const yaml = `key: value`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("handles list item with just dash", () => {
      const yaml = `items:
  -
  - second`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("handles multiple blank lines between content", () => {
      const yaml = `name: test


version: 1.0.0


enabled: true`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });
  });

  describe("error reporting", () => {
    test("includes line numbers in errors", () => {
      const yaml = `name: test
version 1.0.0
enabled: true`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].line).toBe(2);
      expect(typeof result.errors[0].line).toBe("number");
    });

    test("includes column information when available", () => {
      const yaml = `: value`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].column).toBeDefined();
      expect(typeof result.errors[0].column).toBe("number");
    });

    test("includes error message", () => {
      const yaml = `name test`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].message).toBeDefined();
      expect(typeof result.errors[0].message).toBe("string");
      expect(result.errors[0].message.length).toBeGreaterThan(0);
    });

    test("includes context for errors", () => {
      const yaml = `name: test
version 1.0.0
enabled: true`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].context).toBeDefined();
      expect(typeof result.errors[0].context).toBe("string");
      expect(result.errors[0].context).toContain("version 1.0.0");
    });

    test("reports multiple errors when present", () => {
      const yaml = `name test
version 1.0.0
enabled true`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(1);
    });

    test("error context highlights problematic line", () => {
      const yaml = `name: test
version 1.0.0
enabled: true`;

      const result = validateYaml(yaml);

      expect(result.valid).toBe(false);
      expect(result.errors[0].context).toContain(">");
    });
  });

  describe("validation result structure", () => {
    test("returns valid=true when no errors", () => {
      const yaml = `name: test`;

      const result = validateYaml(yaml);

      expect(result).toHaveProperty("valid");
      expect(result).toHaveProperty("errors");
      expect(result.valid).toBe(true);
      expect(Array.isArray(result.errors)).toBe(true);
    });

    test("returns valid=false when errors present", () => {
      const yaml = `name test`;

      const result = validateYaml(yaml);

      expect(result).toHaveProperty("valid");
      expect(result).toHaveProperty("errors");
      expect(result.valid).toBe(false);
      expect(Array.isArray(result.errors)).toBe(true);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("error objects have required structure", () => {
      const yaml = `name test`;

      const result = validateYaml(yaml);

      expect(result.errors.length).toBeGreaterThan(0);
      const error = result.errors[0];
      expect(error).toHaveProperty("line");
      expect(error).toHaveProperty("message");
      expect(typeof error.line).toBe("number");
      expect(typeof error.message).toBe("string");
    });
  });
});

