    75→function validateLine(
    76→  line: string,
    77→  lineNum: number,
    78→  state: ParserState,
    79→  errors: ValidationError[],
    80→  allLines: string[]
    81→): void {
    82→  if (line.trim().length === 0) {
    83→    return;
    84→  }
    85→
    86→  const commentIndex = findCommentStart(line, state);
    87→  const effectiveLine = commentIndex >= 0 ? line.substring(0, commentIndex) : line;
    88→
    89→  if (effectiveLine.trim().length === 0) {
    90→    return;
    91→  }
    92→
    93→  checkIndentation(effectiveLine, lineNum, state, errors, allLines);
    94→  checkKeyValueSyntax(effectiveLine, lineNum, state, errors, allLines);
    95→  checkListItemFormat(effectiveLine, lineNum, errors, allLines);
    96→  updateBracketState(effectiveLine, lineNum, state);
    97→}
    98→
    99→function findCommentStart(line: string, state: ParserState): number {
   100→  for (let i = 0; i < line.length; i++) {
   101→    const char = line[i];
   102→
   103→    if (char === '"' || char === "'") {
   104→      if (state.inQuote && state.inQuote.char === char) {
   105→        state.inQuote = null;
   106→      } else if (!state.inQuote) {
   107→        state.inQuote = { char, line: 0, column: i };
   108→      }
   109→    }
   110→
   111→    if (char === '#' && !state.inQuote) {
   112→      return i;
   113→    }
   114→  }
   115→
   116→  return -1;
   117→}
   118→
   119→function checkIndentation(
   120→  line: string,
   121→  lineNum: number,
   122→  state: ParserState,
   123→  errors: ValidationError[],
   124→  allLines: string[]
   125→): void {
   126→  const indent = line.search(/\S/);
   127→
   128→  if (indent === -1) {
   129→    return;
   130→  }
   131→
   132→  const indentStr = line.substring(0, indent);
   133→  if (indentStr.includes('\t') && indentStr.includes(' ')) {
   134→    errors.push({
   135→      line: lineNum,
   136→      column: 0,
   137→      message: 'Mixed tabs and spaces in indentation',
   138→      context: getContext(allLines, lineNum - 1),
   139→    });
   140→    return;
   141→  }
   142→
   143→  if (indent > state.previousIndent) {
   144→    const jump = indent - state.previousIndent;
   145→    if (state.previousIndent > 0 && jump > 4) {
   146→      errors.push({
   147→        line: lineNum,
   148→        column: 0,
   149→        message: `Indentation jump too large - expected ${state.previousIndent + 2} spaces, found ${indent}`,
   150→        context: getContext(allLines, lineNum - 1),
   151→      });
   152→    }
   153→    state.indentStack.push(indent);
   154→  } else if (indent < state.previousIndent) {
   155→    while (state.indentStack.length > 0 && state.indentStack[state.indentStack.length - 1] > indent) {
   156→      state.indentStack.pop();
   157→    }
   158→
   159→    if (state.indentStack.length > 0 && state.indentStack[state.indentStack.length - 1] !== indent) {
   160→      errors.push({
   161→        line: lineNum,
   162→        column: 0,
   163→        message: `Inconsistent indentation - ${indent} spaces does not match any previous level`,
   164→        context: getContext(allLines, lineNum - 1),
   165→      });
   166→    }
   167→  }
   168→
   169→  state.previousIndent = indent;
   170→}
   171→
   172→function checkKeyValueSyntax(
   173→  line: string,
   174→  lineNum: number,
   175→  state: ParserState,
   176→  errors: ValidationError[],
   177→  allLines: string[]
   178→): void {
   179→  const trimmed = line.trim();
   180→
   181→  if (trimmed.startsWith('-')) {
   182→    return;
   183→  }
   184→
   185→  if (trimmed.startsWith('[') || trimmed.startsWith('{')) {
   186→    return;
   187→  }
   188→
   189→  if (!trimmed.includes(':')) {
   190→    if (trimmed.length > 0 && !trimmed.match(/^[\[\]{},"']/) && !isScalarValue(trimmed)) {
   191→      errors.push({
   192→        line: lineNum,
   193→        column: line.search(/\S/),
   194→        message: 'Missing colon in key-value pair',
   195→        context: getContext(allLines, lineNum - 1),
   196→      });
   197→    }
   198→  } else {
   199→    const colonIndex = trimmed.indexOf(':');
   200→    const key = trimmed.substring(0, colonIndex).trim();
   201→
   202→    if (key.length === 0) {
   203→      errors.push({
   204→        line: lineNum,
   205→        column: line.indexOf(':'),
   206→        message: 'Empty key before colon',
   207→        context: getContext(allLines, lineNum - 1),
   208→      });
   209→    }
   210→  }
   211→}
   212→
   213→function checkListItemFormat(
   214→  line: string,
   215→  lineNum: number,
   216→  errors: ValidationError[],
   217→  allLines: string[]
   218→): void {
   219→  const trimmed = line.trim();
   220→
   221→  if (!trimmed.startsWith('-')) {
   222→    return;
   223→  }
   224→
   225→  if (trimmed.length === 1) {
   226→    return;
   227→  }
   228→
   229→  const afterDash = trimmed[1];
   230→  if (afterDash !== ' ' && afterDash !== '\t') {
   231→    errors.push({
   232→      line: lineNum,
   233→      column: line.indexOf('-') + 1,
   234→      message: 'List item dash must be followed by space',
   235→      context: getContext(allLines, lineNum - 1),
   236→    });
   237→  }
   238→}
   239→
   240→function updateBracketState(
   241→  line: string,
   242→  lineNum: number,
   243→  state: ParserState
   244→): void {
   245→  const quoteState = { char: '', active: false };
   246→
   247→  for (let i = 0; i < line.length; i++) {
   248→    const char = line[i];
   249→
   250→    if (char === '"' || char === "'") {
   251→      if (quoteState.active && quoteState.char === char) {
   252→        quoteState.active = false;
   253→      } else if (!quoteState.active) {
   254→        quoteState.active = true;
   255→        quoteState.char = char;
   256→      }
   257→      continue;
   258→    }
   259→
   260→    if (quoteState.active) {
   261→      continue;
   262→    }
   263→
   264→    if (char === '[' || char === '{') {
   265→      state.openBrackets.push({ char, line: lineNum, column: i });
   266→    } else if (char === ']') {
   267→      if (state.openBrackets.length === 0 || state.openBrackets[state.openBrackets.length - 1].char !== '[') {
   268→        continue;
   269→      }
   270→      state.openBrackets.pop();
   271→    } else if (char === '}') {
   272→      if (state.openBrackets.length === 0 || state.openBrackets[state.openBrackets.length - 1].char !== '{') {
   273→        continue;
   274→      }
   275→      state.openBrackets.pop();
   276→    }
   277→  }
   278→}
   279→
   280→function isScalarValue(text: string): boolean {
   281→  const scalarPatterns = [
   282→    /^true$/i,
   283→    /^false$/i,
   284→    /^null$/i,
   285→    /^~$/,
   286→    /^-?\d+$/,
   287→    /^-?\d+\.\d+$/,
   288→    /^0x[0-9a-fA-F]+$/,
   289→  ];
   290→
   291→  return scalarPatterns.some(pattern => pattern.test(text.trim()));
   292→}
   293→
   294→function getContext(lines: string[], lineIndex: number): string {
   295→  const contextLines: string[] = [];
   296→
   297→  const start = Math.max(0, lineIndex - 1);
   298→  const end = Math.min(lines.length - 1, lineIndex + 1);
   299→
   300→  for (let i = start; i <= end; i++) {
   301→    const prefix = i === lineIndex ? '> ' : '  ';
   302→    contextLines.push(`${prefix}${lines[i]}`);
   303→  }
   304→
   305→  return contextLines.join('\n');
   306→}
