// Minimal YAML Validator - Pattern-based approach
// DISPOSABLE EXPERIMENTAL CODE

interface ValidationError {
  line: number;
  column: number;
  message: string;
  type: 'indentation' | 'syntax' | 'delimiter';
}

interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

export function validateYaml(content: string): ValidationResult {
  const lines = content.split('\n');
  const errors: ValidationError[] = [];
  const indentStack: number[] = [];
  const delimiterStack: { char: string; line: number; col: number }[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNum = i + 1;

    // Skip empty lines and comments
    const trimmed = line.trim();
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue;
    }

    // Check indentation consistency (must be spaces, consistent levels)
    const leadingSpaces = line.match(/^(\s*)/)?.[1] || '';
    if (leadingSpaces.includes('\t')) {
      errors.push({
        line: lineNum,
        column: leadingSpaces.indexOf('\t') + 1,
        message: 'Tabs not allowed in YAML indentation, use spaces',
        type: 'indentation'
      });
    }

    const indent = leadingSpaces.length;

    // Check for inconsistent indentation (not a multiple of common patterns)
    // Common YAML uses 2-space or 4-space indentation
    if (indent > 0 && indent % 2 !== 0) {
      errors.push({
        line: lineNum,
        column: 1,
        message: `Inconsistent indentation: ${indent} spaces (should be multiple of 2)`,
        type: 'indentation'
      });
    }

    // Check key-value pair syntax
    const keyValueMatch = trimmed.match(/^([^:#\[\]{}]+):\s*(.*)$/);
    if (keyValueMatch && trimmed.includes(':')) {
      const [, key, value] = keyValueMatch;

      // Check for invalid characters in unquoted keys
      if (!/^[a-zA-Z0-9_\-\.]+$/.test(key.trim()) && !key.startsWith('"') && !key.startsWith("'")) {
        // This might be a quoted key or special case - be permissive for now
      }

      // Check for missing space after colon (common error)
      const colonIndex = line.indexOf(':');
      if (colonIndex > 0 && colonIndex < line.length - 1) {
        const afterColon = line[colonIndex + 1];
        if (afterColon !== ' ' && afterColon !== '\n' && line.trim()[colonIndex + 1]) {
          errors.push({
            line: lineNum,
            column: colonIndex + 2,
            message: 'Missing space after colon in key-value pair',
            type: 'syntax'
          });
        }
      }
    }

    // Check delimiter matching for [], {}, quotes
    for (let j = 0; j < line.length; j++) {
      const char = line[j];

      if (char === '[' || char === '{') {
        delimiterStack.push({ char, line: lineNum, col: j + 1 });
      } else if (char === ']' || char === '}') {
        const expected = char === ']' ? '[' : '{';
        const last = delimiterStack[delimiterStack.length - 1];

        if (!last || last.char !== expected) {
          errors.push({
            line: lineNum,
            column: j + 1,
            message: `Unmatched ${char} delimiter`,
            type: 'delimiter'
          });
        } else {
          delimiterStack.pop();
        }
      }
    }

    // Check for common YAML list syntax
    if (trimmed.startsWith('-')) {
      const afterDash = trimmed[1];
      if (afterDash && afterDash !== ' ' && afterDash !== '\n') {
        errors.push({
          line: lineNum,
          column: indent + 2,
          message: 'Missing space after list indicator "-"',
          type: 'syntax'
        });
      }
    }
  }

  // Check for unclosed delimiters
  for (const delimiter of delimiterStack) {
    errors.push({
      line: delimiter.line,
      column: delimiter.col,
      message: `Unclosed ${delimiter.char} delimiter`,
      type: 'delimiter'
    });
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

#!/usr/bin/env bun
// DISPOSABLE EXPERIMENTAL CODE
// Tests minimal YAML validator against samples and compares with native parser

import { validateYaml } from './minimal-validator';
import { validSamples, invalidSamples, advancedYaml } from './test-samples';

interface TestResult {
  category: string;
  sample: string;
  minimalValid: boolean;
  minimalErrors: number;
  nativeValid: boolean;
  nativeError: string | null;
  match: boolean;
  falsePositive: boolean;
  falseNegative: boolean;
}

function testWithNativeParser(yaml: string): { valid: boolean; error: string | null } {
  try {
    // Bun has native YAML support via Bun.YAML
    const parsed = Bun.YAML.parse(yaml);
    return { valid: true, error: null };
  } catch (err) {
    return { valid: false, error: err instanceof Error ? err.message : String(err) };
  }
}

function runTests() {
  const results: TestResult[] = [];

  console.log('=== Testing Valid YAML Samples ===\n');

  for (const [name, yaml] of Object.entries(validSamples)) {
    const minimalResult = validateYaml(yaml);
    const nativeResult = testWithNativeParser(yaml);

    const falsePositive = !minimalResult.valid && nativeResult.valid;
    const match = minimalResult.valid === nativeResult.valid;

    results.push({
      category: 'valid',
      sample: name,
      minimalValid: minimalResult.valid,
      minimalErrors: minimalResult.errors.length,
      nativeValid: nativeResult.valid,
      nativeError: nativeResult.error,
      match,
      falsePositive,
      falseNegative: false,
    });

    console.log(`${name}:`);
    console.log(`  Minimal: ${minimalResult.valid ? '✓ VALID' : '✗ INVALID'}`);
    if (!minimalResult.valid) {
      minimalResult.errors.forEach(err => {
        console.log(`    Line ${err.line}, Col ${err.column}: ${err.message}`);
      });
    }
    console.log(`  Native:  ${nativeResult.valid ? '✓ VALID' : '✗ INVALID'}`);
    if (!nativeResult.valid) {
      console.log(`    ${nativeResult.error}`);
    }
    console.log(`  Match: ${match ? '✓' : '✗ FALSE POSITIVE'}\n`);
  }

  console.log('\n=== Testing Invalid YAML Samples ===\n');

  for (const [name, yaml] of Object.entries(invalidSamples)) {
    const minimalResult = validateYaml(yaml);
    const nativeResult = testWithNativeParser(yaml);

    const falseNegative = minimalResult.valid && !nativeResult.valid;
    const match = minimalResult.valid === nativeResult.valid;

    results.push({
      category: 'invalid',
      sample: name,
      minimalValid: minimalResult.valid,
      minimalErrors: minimalResult.errors.length,
      nativeValid: nativeResult.valid,
      nativeError: nativeResult.error,
      match,
      falsePositive: false,
      falseNegative,
    });

    console.log(`${name}:`);
    console.log(`  Minimal: ${minimalResult.valid ? '✓ VALID' : '✗ INVALID'} (${minimalResult.errors.length} errors)`);
    if (!minimalResult.valid) {
      minimalResult.errors.forEach(err => {
        console.log(`    Line ${err.line}, Col ${err.column}: [${err.type}] ${err.message}`);
      });
    }
    console.log(`  Native:  ${nativeResult.valid ? '✓ VALID' : '✗ INVALID'}`);
    if (!nativeResult.valid) {
      console.log(`    ${nativeResult.error}`);
    }
    console.log(`  Match: ${match ? '✓' : (falseNegative ? '✗ FALSE NEGATIVE' : '✓')}\n`);
  }

  console.log('\n=== Testing Advanced YAML Features ===\n');

  for (const [name, yaml] of Object.entries(advancedYaml)) {
    const minimalResult = validateYaml(yaml);
    const nativeResult = testWithNativeParser(yaml);

    const match = minimalResult.valid === nativeResult.valid;

    results.push({
      category: 'advanced',
      sample: name,
      minimalValid: minimalResult.valid,
      minimalErrors: minimalResult.errors.length,
      nativeValid: nativeResult.valid,
      nativeError: nativeResult.error,
      match,
      falsePositive: !minimalResult.valid && nativeResult.valid,
      falseNegative: minimalResult.valid && !nativeResult.valid,
    });

    console.log(`${name}:`);
    console.log(`  Minimal: ${minimalResult.valid ? '✓ VALID' : '✗ INVALID'}`);
    if (!minimalResult.valid) {
      minimalResult.errors.forEach(err => {
        console.log(`    Line ${err.line}, Col ${err.column}: ${err.message}`);
      });
    }
    console.log(`  Native:  ${nativeResult.valid ? '✓ VALID' : '✗ INVALID'}`);
    console.log(`  Note: ${match ? 'Matches' : 'Differs (expected for advanced features)'}\n`);
  }

  // Calculate statistics
  console.log('\n=== STATISTICS ===\n');

  const validTests = results.filter(r => r.category === 'valid');
  const invalidTests = results.filter(r => r.category === 'invalid');
  const advancedTests = results.filter(r => r.category === 'advanced');

  const falsePositives = results.filter(r => r.falsePositive).length;
  const falseNegatives = results.filter(r => r.falseNegative).length;
  const totalTests = results.length;
  const matches = results.filter(r => r.match).length;

  const detectionRate = invalidTests.length > 0
    ? ((invalidTests.filter(r => !r.minimalValid).length / invalidTests.length) * 100).toFixed(1)
    : 'N/A';

  const falsePositiveRate = validTests.length > 0
    ? ((falsePositives / validTests.length) * 100).toFixed(1)
    : 'N/A';

  const falseNegativeRate = invalidTests.length > 0
    ? ((falseNegatives / invalidTests.length) * 100).toFixed(1)
    : 'N/A';

  console.log(`Total Tests: ${totalTests}`);
  console.log(`Valid Samples: ${validTests.length}`);
  console.log(`Invalid Samples: ${invalidTests.length}`);
  console.log(`Advanced Features: ${advancedTests.length}`);
  console.log(`\nAccuracy:`);
  console.log(`  Matches with native parser: ${matches}/${totalTests} (${((matches/totalTests)*100).toFixed(1)}%)`);
  console.log(`  Detection rate (invalid caught): ${detectionRate}%`);
  console.log(`  False positive rate: ${falsePositiveRate}%`);
  console.log(`  False negative rate: ${falseNegativeRate}%`);

  console.log(`\nError Breakdown:`);
  console.log(`  False Positives (rejected valid YAML): ${falsePositives}`);
  console.log(`  False Negatives (accepted invalid YAML): ${falseNegatives}`);

  // Detailed breakdown of mismatches
  const mismatches = results.filter(r => !r.match);
  if (mismatches.length > 0) {
    console.log(`\nMismatches with native parser:`);
    mismatches.forEach(m => {
      console.log(`  - ${m.sample} (${m.category}): Minimal=${m.minimalValid}, Native=${m.nativeValid}`);
    });
  }

  return results;
}

runTests();

