     8→
     9→Validates YAML file syntax without adding external dependencies.
    10→
    11→Arguments:
    12→  <filepath>    Path to the YAML file to validate
    13→
    14→Exit codes:
    15→  0    Valid YAML
    16→  1    Invalid YAML
    17→  2    I/O error (file not found, permission denied, etc.)
    18→
    19→Examples:
    20→  bun run validate-yaml config.yaml
    21→  bun run validate-yaml ./configs/app.yml
    22→`);
    23→}
    24→
    25→function main(): void {
    26→  const args = process.argv.slice(2);
    27→
    28→  if (args.length === 0) {
    29→    displayUsage();
    30→    process.exit(2);
    31→  }
    32→
    33→  const filePath = args[0];
    34→
    35→  try {
    36→    const content = readFileSync(filePath, 'utf-8');
    37→    const result = validateYaml(content);
    38→
    39→    if (result.valid) {
    40→      console.log(`✓ Valid YAML: ${filePath}`);
    41→      process.exit(0);
    42→    } else {
    43→      console.log(`✗ Invalid YAML: ${filePath}`);
    44→      for (const error of result.errors) {
    45→        const columnInfo = error.column !== undefined ? `, column ${error.column}` : '';
    46→        console.log(`  Line ${error.line}${columnInfo}: ${error.message}`);
    47→
    48→        if (error.context) {
    49→          const contextLines = error.context.split('\n');
    50→          for (const line of contextLines) {
    51→            console.log(`    ${line}`);
    52→          }
    53→        }
    54→      }
    55→      process.exit(1);
    56→    }
    57→  } catch (err) {
    58→    if (err instanceof Error) {
    59→      if ('code' in err && err.code === 'ENOENT') {
    60→        console.error(`✗ Error: File not found: ${filePath}`);
    61→        process.exit(2);
    62→      } else if ('code' in err && err.code === 'EACCES') {
    63→        console.error(`✗ Error: Permission denied: ${filePath}`);
